def dia(n):
    return {'texto': f'DIA {n}', 'pos': 'topo', 'cor': '#FFD23F'}


def duo(bg='porao_cortina', voce=None, bia=None, **kw):
    """você à esquerda, Bia à direita, sentados nos colchonetes."""
    v = dict(sit=True); v.update(voce or {})
    b = dict(sit=True, facing=-1); b.update(bia or {})
    return S(bg, C('voce', 'a', None, **v), C('bia', 'b', None, **b), **kw)


